package com.yonlab.vision;
import java.util.*;
/** Pixel-aspect-aware 2D geometry. Missing observations remain absent. */
final class CoachGeometry {
 static Double angle(PoseGeometry.Point a,PoseGeometry.Point b,PoseGeometry.Point c,int w,int h){if(!PoseGeometry.visible(a)||!PoseGeometry.visible(b)||!PoseGeometry.visible(c)||w<1||h<1)return null;double ux=(a.x-b.x)*w,uy=(a.y-b.y)*h,vx=(c.x-b.x)*w,vy=(c.y-b.y)*h;double scale=Math.hypot(ux,uy)*Math.hypot(vx,vy);if(scale<1e-8)return null;return Math.toDegrees(Math.acos(Math.max(-1,Math.min(1,(ux*vx+uy*vy)/scale))));}
 static Map<String,Double> analyze(List<PoseGeometry.Point> points,int w,int h){PoseGeometry.Point[] p=new PoseGeometry.Point[33];for(PoseGeometry.Point a:PoseGeometry.visible(points))p[a.id]=a;Map<String,Double> out=new LinkedHashMap<>();put(out,"leftElbow",angle(p[11],p[13],p[15],w,h));put(out,"rightElbow",angle(p[12],p[14],p[16],w,h));put(out,"leftKnee",angle(p[23],p[25],p[27],w,h));put(out,"rightKnee",angle(p[24],p[26],p[28],w,h));put(out,"leftHip",angle(p[11],p[23],p[25],w,h));put(out,"rightHip",angle(p[12],p[24],p[26],w,h));if(p[11]!=null&&p[12]!=null){double dx=Math.abs((p[11].x-p[12].x)*w),dy=Math.abs((p[11].y-p[12].y)*h);if(Math.hypot(dx,dy)>1e-5)out.put("shoulderTilt",Math.toDegrees(Math.atan2(dy,dx)));}if(p[11]!=null&&p[12]!=null&&p[23]!=null&&p[24]!=null){double dx=Math.abs(((p[11].x+p[12].x)-(p[23].x+p[24].x))*.5*w),dy=Math.abs(((p[11].y+p[12].y)-(p[23].y+p[24].y))*.5*h);if(Math.hypot(dx,dy)>1e-5)out.put("trunkLean",Math.toDegrees(Math.atan2(dx,dy)));}return out;}
 private static void put(Map<String,Double> out,String key,Double value){if(value!=null&&!Double.isNaN(value)&&!Double.isInfinite(value))out.put(key,value);}
 static String observation(Map<String,Double> a){Double knee=mean(a,"leftKnee","rightKnee"),hip=mean(a,"leftHip","rightHip"),elbow=mean(a,"leftElbow","rightElbow"),trunk=a.get("trunkLean");if(a.size()<2)return "관측 지점 부족";if(knee!=null&&hip!=null&&knee<135&&hip<150)return "무릎과 고관절 굽힘";if(elbow!=null&&trunk!=null&&elbow<135&&trunk>55)return "상체 지지 · 팔꿈치 굽힘";if(knee!=null&&knee>160&&trunk!=null&&trunk<20)return "선 자세 · 정렬 관측";return "관절 움직임 관측";}
 static Double mean(Map<String,Double> a,String x,String y){Double l=a.get(x),r=a.get(y);if(l==null)return r;if(r==null)return l;return Double.valueOf((l.doubleValue()+r.doubleValue())*.5);}
}
